import React, { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { supabase } from '../lib/supabase'
import { useSiteContent } from '../context/SiteContentContext'

const CORE = { home:'Home', about:'About', services:'Services', projects:'Projects', team:'Team', contact:'Contact' }
const TYPES = [
  ['hero','Hero'],['text','Text'],['image','Image'],['button','Button'],['video','Video'],
  ['divider','Divider'],['spacer','Spacer'],['services','Services'],['projects','Projects'],
  ['team','Team'],['values','Values'],['contact','Contact']
]
const uid=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`
const clone=x=>JSON.parse(JSON.stringify(x))

function makeBlock(type, settings={}){
  const defaults={
    hero:{eyebrow:'',title:'',description:'',image:'',primaryText:'Discover more',primaryUrl:'/about',secondaryText:'Get in touch',secondaryUrl:'/contact'},
    text:{eyebrow:'',title:'',text:'',alignment:'left'},
    image:{url:'',alt:'',caption:'',height:500,fit:'cover'},
    button:{text:'Learn more',url:'/contact',style:'dark',alignment:'left'},
    video:{url:'',title:'Video',aspect:'16/9'},divider:{},spacer:{height:80},
    services:{eyebrow:'',title:'',description:'',limit:3},projects:{eyebrow:'',title:'',description:'',limit:3},
    team:{eyebrow:'',title:'',description:'',limit:0},values:{eyebrow:'',title:'',description:'',limit:0},
    contact:{eyebrow:'CONTACT',title:"Let's start a conversation.",description:'We would love to hear from you.'}
  }
  return {id:uid(),type,settings:{...(defaults[type]||{}),...settings},visible:true}
}
function makeSection(name='New section',blocks=[]){return {id:uid(),name,settings:{background:'',padding:'large',maxWidth:1200},blocks,visible:true}}

function coreSeed(slug,s={}){
  const serviceTitle='Thoughtful work, built around your goals.'
  const projectTitle='A few examples of what we create.'
  if(slug==='home') return [
    makeSection('Hero',[makeBlock('hero',{eyebrow:s.hero_eyebrow||s.business_name||'YOUR BUSINESS',title:s.hero_title||'Ideas, expertise, and solutions that move forward.',description:s.hero_description||'',image:s.hero_image||''})]),
    makeSection('Services',[makeBlock('services',{eyebrow:'WHAT WE DO',title:serviceTitle,limit:3})]),
    makeSection('Projects',[makeBlock('projects',{eyebrow:'SELECTED WORK',title:projectTitle,limit:3})])
  ]
  if(slug==='about') return [
    makeSection('About heading',[makeBlock('text',{eyebrow:s.about_eyebrow||'ABOUT US',title:s.about_title||'Purpose, perspective, and a clear direction.',text:s.about_description||''})]),
    makeSection('About story',[makeBlock('image',{url:s.about_image||'',alt:`${s.business_name||'Business'} about`,height:500}),makeBlock('text',{text:[s.about_story,s.about_mission].filter(Boolean).join('\n\n'),alignment:'left'})]),
    makeSection('Values',[makeBlock('values',{eyebrow:s.values_eyebrow||'OUR VALUES',title:s.values_title||'What guides the way we work.',description:s.values_description||'',limit:0})]),
    ...(s.about_quote?[makeSection('Our philosophy',[makeBlock('text',{title:'',text:s.about_quote,alignment:'center'})])]:[])
  ]
  if(slug==='services') return [
    makeSection('Services heading',[makeBlock('text',{eyebrow:s.services_eyebrow||'SERVICES',title:s.services_title||'Expertise shaped around what you need.',text:s.services_description||''})]),
    makeSection('Services list',[makeBlock('services',{eyebrow:'',title:'',limit:0})]),
    makeSection('Contact CTA',[makeBlock('contact',{eyebrow:s.services_cta_eyebrow||'START A CONVERSATION',title:s.services_cta_title||'Have a project in mind?',description:'',})])
  ]
  if(slug==='projects') return [
    makeSection('Projects heading',[makeBlock('text',{eyebrow:s.projects_eyebrow||'PROJECTS',title:s.projects_title||'Selected work and ideas.',text:s.projects_description||''})]),
    makeSection('Projects list',[makeBlock('projects',{eyebrow:'',title:'',limit:0})])
  ]
  if(slug==='team') return [
    makeSection('Team heading',[makeBlock('text',{eyebrow:s.team_eyebrow||'TEAM',title:s.team_title||'The people behind the work.',text:s.team_description||''})]),
    makeSection('Team',[makeBlock('team',{eyebrow:'',title:'',limit:0})])
  ]
  if(slug==='contact') return [makeSection('Contact',[makeBlock('contact',{eyebrow:s.contact_eyebrow||'CONTACT',title:s.contact_title||"Let's start a conversation.",description:s.contact_description||'We would love to hear from you.'})])]
  return [makeSection('Content',[makeBlock('text',{title:'Welcome',text:'Start building your page.'})])]
}

function hydrate(rows,slug,site){
  const s=site||{}
  if(!rows?.length) return coreSeed(slug,s)
  const out=clone(rows)
  const find=t=>out.flatMap(x=>x.blocks||[]).find(b=>b.type===t)
  const patch=(type,p)=>{const b=find(type);if(b)b.settings={...b.settings,...p}}
  if(slug==='home'){
    patch('hero',{eyebrow:s.hero_eyebrow||s.business_name||'YOUR BUSINESS',title:(find('hero')?.settings?.title==='Your headline')?(s.hero_title||''):find('hero')?.settings?.title,description:(find('hero')?.settings?.description==='Tell visitors what you do and why it matters.')?(s.hero_description||''):find('hero')?.settings?.description,image:find('hero')?.settings?.image||s.hero_image||''})
    patch('services',{eyebrow:'WHAT WE DO',title:(find('services')?.settings?.title==='Thoughtful work, built around your goals.'||!find('services')?.settings?.title)?'Thoughtful work, built around your goals.':find('services').settings.title})
    patch('projects',{eyebrow:'SELECTED WORK',title:(find('projects')?.settings?.title==='A few examples of what we create.'||!find('projects')?.settings?.title)?'A few examples of what we create.':find('projects').settings.title})
  }
  if(slug==='about'){
    const texts=out.flatMap(x=>x.blocks||[]).filter(b=>b.type==='text')
    const heading=texts[0],story=texts[1]
    if(heading){heading.settings={...heading.settings,eyebrow:s.about_eyebrow||'ABOUT US',title:(heading.settings.title==='Purpose, perspective, and a clear direction.'||heading.settings.title==='')?(s.about_title||'Purpose, perspective, and a clear direction.'):heading.settings.title,text:(heading.settings.text==='Write your content here.')?(s.about_description||''):heading.settings.text}}
    if(story && story.settings.text==='Write your content here.') story.settings.text=[s.about_story,s.about_mission].filter(Boolean).join('\n\n')
    patch('image',{url:find('image')?.settings?.url||s.about_image||''})
    patch('values',{eyebrow:s.values_eyebrow||'OUR VALUES',title:s.values_title||'What guides the way we work.',description:s.values_description||''})
  }
  if(slug==='services') patch('text',{eyebrow:s.services_eyebrow||'SERVICES',title:(find('text')?.settings?.title==='Write your content here.')?(s.services_title||'Expertise shaped around what you need.'):find('text')?.settings?.title,text:(find('text')?.settings?.text==='Write your content here.')?(s.services_description||''):find('text')?.settings?.text})
  if(slug==='projects') patch('text',{eyebrow:s.projects_eyebrow||'PROJECTS',title:(find('text')?.settings?.title==='Write your content here.')?(s.projects_title||'Selected work and ideas.'):find('text')?.settings?.title,text:(find('text')?.settings?.text==='Write your content here.')?(s.projects_description||''):find('text')?.settings?.text})
  if(slug==='team') patch('text',{eyebrow:s.team_eyebrow||'TEAM',title:(find('text')?.settings?.title==='Write your content here.')?(s.team_title||'The people behind the work.'):find('text')?.settings?.title,text:(find('text')?.settings?.text==='Write your content here.')?(s.team_description||''):find('text')?.settings?.text})
  if(slug==='contact') patch('contact',{eyebrow:s.contact_eyebrow||'CONTACT',title:s.contact_title||"Let's start a conversation.",description:s.contact_description||'We would love to hear from you.'})
  return out
}

export default function PageBuilder(){
  const {id}=useParams(); const navigate=useNavigate(); const isNew=id==='new'
  const {siteContent,services,projects,team,values,socialLinks}=useSiteContent()
  const [page,setPage]=useState(null),[sections,setSections]=useState([]),[selected,setSelected]=useState(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[message,setMessage]=useState(''),[device,setDevice]=useState('desktop'),[modal,setModal]=useState(null),[history,setHistory]=useState([]),[future,setFuture]=useState([]),[drag,setDrag]=useState(null),[header,setHeader]=useState({background:'#ffffff',textColor:'#222222',borderColor:'#e5e5e5',sticky:false,logoSize:18}),[footer,setFooter]=useState({business_name:'',tagline:'',email:'',phone:'',address:'',socials:[]})
  const loaded=useRef(false)

  useEffect(()=>{loadPage()},[id])
  async function loadPage(){
    setLoading(true);setMessage('');loaded.current=false
    if(isNew){
      setPage({id:null,name:'New page',slug:'',title:'New page',description:'',background_image:'',background_color:'',is_published:true,show_in_navigation:false,sort_order:100})
      setSections([makeSection('Hero',[makeBlock('hero')])]);setFooter({business_name:siteContent?.business_name||'',tagline:siteContent?.tagline||'',email:siteContent?.email||'',phone:siteContent?.phone||'',address:siteContent?.address||'',socials:clone(socialLinks||[])});setSelected(null);setHeader(loadHeaderSettings());loaded.current=true;setLoading(false);return
    }
    const {data,error}=await supabase.from('pages').select('*').eq('id',id).single()
    if(error||!data){setMessage(error?.message||'Page not found.');setLoading(false);return}
    const {data:rows,error:be}=await supabase.from('page_blocks').select('*').eq('page_id',id).order('sort_order',{ascending:true})
    if(be){setMessage(`Could not load sections: ${be.message}`);setLoading(false);return}
    const parsed=(rows||[]).filter(r=>r.block_type==='section').map(r=>r.content).filter(Boolean).map(s=>({...s,visible:s.visible!==false,blocks:(s.blocks||[]).map(b=>({...b,visible:b.visible!==false}))}))
    const next=hydrate(parsed,data.slug,siteContent)
    setPage(data);setSections(next);setHeader(loadHeaderSettings());setFooter({business_name:siteContent?.business_name||'',tagline:siteContent?.tagline||'',email:siteContent?.email||'',phone:siteContent?.phone||'',address:siteContent?.address||'',socials:clone(socialLinks||[]) });setSelected(next[0]?.id||null);loaded.current=true;setLoading(false)
  }
  function commit(next,nextPage=page){setHistory(h=>[...h,clone({page,sections})].slice(-40));setFuture([]);setSections(clone(next));if(nextPage!==page)setPage(clone(nextPage))}
  function updatePage(field,value){commit(sections,{...page,[field]:value})}
  function updateSection(id,patch){commit(sections.map(s=>s.id===id?{...s,...patch}:s))}
  function updateBlock(sid,bid,patch){commit(sections.map(s=>s.id===sid?{...s,blocks:s.blocks.map(b=>b.id===bid?{...b,settings:{...b.settings,...patch}}:b)}:s))}
  function addSection(type='section'){const names={hero:'Hero',text:'Text',image:'Image',services:'Services',projects:'Projects',team:'Team',contact:'Contact',section:'New section'};const b=type==='section'?'text':type;const s=makeSection(names[type]||'New section',[makeBlock(b)]);commit([...sections,s]);setSelected(s.id);setModal(null)}
  function addBlock(sid,type){const s=sections.find(x=>x.id===sid);if(!s)return;const b=makeBlock(type);commit(sections.map(x=>x.id===sid?{...x,blocks:[...x.blocks,b]}:x));setSelected(`${sid}:${b.id}`);setModal(null)}
  function removeSection(id){commit(sections.filter(s=>s.id!==id));setSelected(null)}
  function removeBlock(sid,bid){commit(sections.map(s=>s.id===sid?{...s,blocks:s.blocks.filter(b=>b.id!==bid)}:s));setSelected(sid)}
  function duplicateSection(id){const s=sections.find(x=>x.id===id);if(!s)return;const copy=clone(s);copy.id=uid();copy.name=`${copy.name} copy`;copy.blocks=copy.blocks.map(b=>({...b,id:uid()}));const i=sections.findIndex(x=>x.id===id);commit([...sections.slice(0,i+1),copy,...sections.slice(i+1)]);setSelected(copy.id)}
  function moveSection(i,d){const j=i+d;if(j<0||j>=sections.length)return;const a=clone(sections);[a[i],a[j]]=[a[j],a[i]];commit(a)}
  function moveBlock(sid,bid,d){const s=sections.find(x=>x.id===sid);if(!s)return;const i=s.blocks.findIndex(b=>b.id===bid),j=i+d;if(i<0||j<0||j>=s.blocks.length)return;const blocks=clone(s.blocks);[blocks[i],blocks[j]]=[blocks[j],blocks[i]];commit(sections.map(x=>x.id===sid?{...x,blocks}:x));setSelected(`${sid}:${bid}`)}
  function duplicateBlock(sid,bid){const s=sections.find(x=>x.id===sid),b=s?.blocks.find(x=>x.id===bid);if(!b)return;const copy=clone(b);copy.id=uid();copy.settings={...(copy.settings||{})};const i=s.blocks.findIndex(x=>x.id===bid);const blocks=[...s.blocks.slice(0,i+1),copy,...s.blocks.slice(i+1)];commit(sections.map(x=>x.id===sid?{...x,blocks}:x));setSelected(`${sid}:${copy.id}`)}
  function toggleSection(id){const s=sections.find(x=>x.id===id);if(s)updateSection(id,{visible:s.visible===false})}
  function toggleBlock(sid,bid){const s=sections.find(x=>x.id===sid),b=s?.blocks.find(x=>x.id===bid);if(!b)return;commit(sections.map(x=>x.id===sid?{...x,blocks:x.blocks.map(y=>y.id===bid?{...y,visible:y.visible===false}:y)}:x))}
  function undo(){if(!history.length)return;const prev=history.at(-1);setFuture(f=>[...f,clone({page,sections})]);setHistory(h=>h.slice(0,-1));setPage(prev.page);setSections(prev.sections)}
  function redo(){if(!future.length)return;const next=future.at(-1);setHistory(h=>[...h,clone({page,sections})]);setFuture(f=>f.slice(0,-1));setPage(next.page);setSections(next.sections)}
  async function uploadPageBackground(file){if(!file)return;setMessage('Uploading background…');const ext=(file.name.split('.').pop()||'jpg').toLowerCase();const path=`pages/background-${uid()}.${ext}`;const {error}=await supabase.storage.from('site-images').upload(path,file,{upsert:false});if(error){setMessage(`Upload failed: ${error.message}`);return}const {data}=supabase.storage.from('site-images').getPublicUrl(path);updatePage('background_image',data.publicUrl);setMessage('Background uploaded. Save to publish it.')}
  async function uploadImage(file,sid,bid){if(!file)return;setMessage('Uploading image…');const ext=(file.name.split('.').pop()||'jpg').toLowerCase();const path=`pages/${uid()}.${ext}`;const {error}=await supabase.storage.from('site-images').upload(path,file,{upsert:false});if(error){setMessage(`Upload failed: ${error.message}`);return}const {data}=supabase.storage.from('site-images').getPublicUrl(path);updateBlock(sid,bid,{url:data.publicUrl,image:data.publicUrl});setMessage('Image uploaded. Save to publish it.')}
  async function save(){
    if(!page?.name?.trim()){setMessage('Give the page a name.');return}if(!page?.slug?.trim()){setMessage('Give the page a URL slug.');return}
    setSaving(true);setMessage('Saving…');
    const pageId=page.id||uid();
    const slug=page.slug.trim().toLowerCase().replace(/^\/+/, '').replace(/\s+/g,'-').replace(/[^a-z0-9-_]/g,'');
    const row={id:pageId,name:page.name.trim(),slug,title:page.title||page.name.trim(),description:page.description||'',background_image:page.background_image||'',background_color:page.background_color||'',is_published:page.is_published!==false,show_in_navigation:!!page.show_in_navigation,sort_order:Number(page.sort_order)||0};
    const {error:pe}=await supabase.from('pages').upsert(row,{onConflict:'id'});
    if(pe){setMessage(`Could not save page: ${pe.message}`);setSaving(false);return}
    const {error:de}=await supabase.from('page_blocks').delete().eq('page_id',pageId);
    if(de){setMessage(`Page saved, but sections could not be replaced: ${de.message}`);setSaving(false);return}
    const rows=sections.map((s,i)=>({id:uid(),page_id:pageId,block_type:'section',content:{...s,visible:s.visible!==false,blocks:(s.blocks||[]).map(b=>({...b,visible:b.visible!==false}))},sort_order:i}));
    if(rows.length){const {error:be}=await supabase.from('page_blocks').insert(rows);if(be){setMessage(`Page saved, but sections failed: ${be.message}`);setSaving(false);return}}

    // Core pages also feed the existing public React pages through site_content.
    // Keep that existing site data in sync so a visual-editor save is immediately visible publicly.
    const coreSlug=slug==='home'?'home':slug;
    const patch={};
    const blocks=sections.flatMap(s=>s.blocks||[]).filter(b=>b.visible!==false);
    const first=t=>blocks.find(b=>b.type===t)?.settings||{};
    const texts=blocks.filter(b=>b.type==='text').map(b=>b.settings||{});
    if(coreSlug==='home'){
      const h=first('hero'), sv=first('services'), pr=first('projects');
      if(h.eyebrow!=null) patch.hero_eyebrow=h.eyebrow; if(h.title!=null) patch.hero_title=h.title; if(h.description!=null) patch.hero_description=h.description; if(h.image!=null) patch.hero_image=h.image;
      if(sv.eyebrow!=null) patch.services_eyebrow=sv.eyebrow; if(sv.title!=null) patch.services_title=sv.title;
      if(pr.eyebrow!=null) patch.projects_eyebrow=pr.eyebrow; if(pr.title!=null) patch.projects_title=pr.title;
    } else if(coreSlug==='about'){
      const heading=texts[0]||{}, story=texts[1]||{}, img=first('image'), val=first('values');
      if(heading.eyebrow!=null) patch.about_eyebrow=heading.eyebrow; if(heading.title!=null) patch.about_title=heading.title; if(heading.text!=null) patch.about_description=heading.text;
      if(story.text!=null){const parts=String(story.text).split(/\n\n/); patch.about_story=parts[0]||''; patch.about_mission=parts.slice(1).join('\n\n')||''}
      if(img.url!=null) patch.about_image=img.url; if(val.eyebrow!=null) patch.values_eyebrow=val.eyebrow; if(val.title!=null) patch.values_title=val.title; if(val.description!=null) patch.values_description=val.description;
      const quote=texts[2]; if(quote?.text!=null) patch.about_quote=quote.text;
    } else if(coreSlug==='services'){
      const h=texts[0]||{}, c=first('contact'); if(h.eyebrow!=null) patch.services_eyebrow=h.eyebrow; if(h.title!=null) patch.services_title=h.title; if(h.text!=null) patch.services_description=h.text;
      if(c.eyebrow!=null) patch.services_cta_eyebrow=c.eyebrow; if(c.title!=null) patch.services_cta_title=c.title;
    } else if(coreSlug==='projects'){const h=texts[0]||{}; if(h.eyebrow!=null) patch.projects_eyebrow=h.eyebrow; if(h.title!=null) patch.projects_title=h.title; if(h.text!=null) patch.projects_description=h.text}
    else if(coreSlug==='team'){const h=texts[0]||{}; if(h.eyebrow!=null) patch.team_eyebrow=h.eyebrow; if(h.title!=null) patch.team_title=h.title; if(h.text!=null) patch.team_description=h.text}
    else if(coreSlug==='contact'){const c=first('contact'); if(c.eyebrow!=null) patch.contact_eyebrow=c.eyebrow; if(c.title!=null) patch.contact_title=c.title; if(c.description!=null) patch.contact_description=c.description}
    if(Object.keys(patch).length && siteContent?.id){
      const {error:ce}=await supabase.from('site_content').update(patch).eq('id',siteContent.id);
      if(ce){setMessage(`Saved editor layout, but public content sync failed: ${ce.message}`);setSaving(false);return}
    }
    if(siteContent?.id){
      const {error:fe}=await supabase.from('site_content').update({business_name:footer.business_name,tagline:footer.tagline,email:footer.email,phone:footer.phone,address:footer.address}).eq('id',siteContent.id)
      if(fe){setMessage(`Page saved, but footer content could not be saved: ${fe.message}`);setSaving(false);return}
    }
    // Sync the editable global social links: update existing, insert new, delete removed.
    if(Array.isArray(footer.socials)){
      const originalIds=(socialLinks||[]).map(s=>s?.id).filter(Boolean)
      const currentIds=footer.socials.map(s=>s?.id).filter(Boolean)
      const removedIds=originalIds.filter(id=>!currentIds.includes(id))
      if(removedIds.length){
        const {error:xd}=await supabase.from('social_links').delete().in('id',removedIds)
        if(xd){setMessage(`Page saved, but removed social links could not be deleted: ${xd.message}`);setSaving(false);return}
      }
      for(const social of footer.socials){
        if(!social) continue
        const payload={name:social.name||'Social',url:social.url||'',icon:social.icon||''}
        if(social.id){
          const {error:se}=await supabase.from('social_links').update(payload).eq('id',social.id)
          if(se){setMessage(`Page saved, but social links could not be saved: ${se.message}`);setSaving(false);return}
        }else{
          const {data:ins,error:ie}=await supabase.from('social_links').insert(payload).select().single()
          if(ie){setMessage(`Page saved, but new social link could not be added: ${ie.message}`);setSaving(false);return}
          if(ins){ social.id=ins.id }
        }
      }
    }
    saveHeaderSettings(header); const newPage={...row,id:pageId};setPage(newPage);setMessage('Saved ✓');setSaving(false);
    if(isNew)navigate(`/admin/pages/${pageId}`,{replace:true})
  }
  if(loading)return <div className="editor-loading">Loading editor…</div>
  const selectedSection=sections.find(s=>s.id===selected)||sections.find(s=>s.id===String(selected||'').split(':')[0])||null
  const selectedBlock=selectedSection?.blocks?.find(b=>b.id===String(selected||'').split(':')[1])||null
  const footerSelected=selected==='__footer'
  return <div className="shopify-editor">
    <header className="se-topbar"><button className="se-back" onClick={()=>navigate('/admin')}>←</button><div className="se-title"><strong>{page?.name||'Page'}</strong><span className={page?.is_published===false?'draft':''}>{page?.is_published===false?'Draft':'Published'}</span></div><div className="se-toolbar"><button onClick={undo} disabled={!history.length} title="Undo">↶</button><button onClick={redo} disabled={!future.length} title="Redo">↷</button><div className="se-device"><button className={device==='desktop'?'active':''} onClick={()=>setDevice('desktop')}>▣</button><button className={device==='mobile'?'active':''} onClick={()=>setDevice('mobile')}>▯</button></div><button className="se-preview" onClick={()=>window.open(`${window.location.origin}${import.meta.env.BASE_URL}${page?.slug==='home'?'':(page?.slug||'')}`,'_blank')}>Preview</button><button className="se-publish" disabled={saving} onClick={()=>{setPage(p=>({...p,is_published:true}));setTimeout(save,0)}}>{saving?'Publishing…':'Publish'}</button><button className="se-save" disabled={saving} onClick={save}>{saving?'Saving…':'Save'}</button></div></header>
    <div className="se-workspace">
      <aside className="se-left"><div className="se-panel-head"><span>PAGE STRUCTURE</span><button onClick={()=>setModal({kind:'section'})}>＋</button></div><div className="se-tree"><div className={`se-tree-row se-global-tree ${selected==='__header'?'selected':''}`} onClick={()=>setSelected('__header')}><span className="grip">≡</span><span className="tree-name">Header</span><span className="tree-more">Global</span></div>
        {sections.map((s,i)=><div key={s.id} className={`se-section-tree ${s.visible===false?'is-hidden':''}`}><div className={`se-tree-row ${selected===s.id?'selected':''}`} draggable onDragStart={()=>setDrag({id:s.id})} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(!drag||drag.id===s.id)return;const from=sections.findIndex(x=>x.id===drag.id);const a=clone(sections);const [x]=a.splice(from,1);a.splice(i,0,x);commit(a);setDrag(null)}} onClick={()=>setSelected(s.id)}><span className="grip">⋮⋮</span><span className="tree-name">{s.name}</span><span className="tree-more">{s.blocks.length}</span><button className="tree-eye" onClick={e=>{e.stopPropagation();toggleSection(s.id)}}>{s.visible===false?'○':'◉'}</button></div>{selectedSection?.id===s.id&&s.blocks.map((b,bi)=><div key={b.id} className={`se-block-row ${selected===`${s.id}:${b.id}`?'selected':''} ${b.visible===false?'is-hidden':''}`} draggable onDragStart={()=>setDrag({id:b.id,sectionId:s.id,kind:'block'})} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(!drag||drag.kind!=='block'||drag.sectionId!==s.id||drag.id===b.id)return;const from=s.blocks.findIndex(x=>x.id===drag.id);const a=clone(s.blocks);const [x]=a.splice(from,1);a.splice(bi,0,x);commit(sections.map(q=>q.id===s.id?{...q,blocks:a}:q));setDrag(null)}} onClick={()=>setSelected(`${s.id}:${b.id}`)}><span>⋮⋮</span>{labelFor(b.type)}<button onClick={e=>{e.stopPropagation();toggleBlock(s.id,b.id)}}>{b.visible===false?'○':'◉'}</button></div>)}</div>)}
      </div><div className={`se-tree-row se-footer-tree ${selected==='__footer'?'selected':''}`} onClick={()=>setSelected('__footer')}><span className="grip">≡</span><span className="tree-name">Footer</span><span className="tree-more">Global</span></div><button className="se-add-section" onClick={()=>setModal({kind:'section'})}>＋ Add section</button><div className="se-left-footer"><button onClick={()=>navigate('/admin/legacy')}>Advanced content manager</button></div></aside>
      <main className="se-canvas"><div className={`se-device-frame ${device}`}><Preview page={page} sections={sections} site={siteContent} services={services} projects={projects} team={team} values={values} selected={selected} setSelected={setSelected} device={device} header={header} footer={footer}/></div></main>
      <aside className="se-right"><Inspector header={selected==='__header'?header:null} updateHeader={p=>{setHeader(h=>({...h,...p}));setMessage('Header changes unsaved')}} footer={footerSelected?footer:null} updateFooter={p=>{setFooter(f=>({...f,...p}));setMessage('Footer changes unsaved')}} section={selectedSection} block={selectedBlock} updateSection={updateSection} updateBlock={updateBlock} removeSection={removeSection} removeBlock={removeBlock} duplicateSection={duplicateSection} moveSection={moveSection} sectionIndex={sections.findIndex(s=>s.id===selectedSection?.id)} addBlock={type=>selectedSection&&addBlock(selectedSection.id,type)} uploadImage={uploadImage} moveBlock={moveBlock} duplicateBlock={duplicateBlock}/><div className="se-settings-bottom"><strong>PAGE</strong><Field label="Page name" value={page?.name} onChange={v=>updatePage('name',v)}/><Field label="Browser title" value={page?.title} onChange={v=>updatePage('title',v)}/><Field label="URL slug" value={page?.slug} onChange={v=>updatePage('slug',v)}/><ColorField label="Page background color" value={page?.background_color||''} onChange={v=>updatePage('background_color',v)}/><Field label="Page background image URL" value={page?.background_image||''} onChange={v=>updatePage('background_image',v)} placeholder="https://…"/><label className="se-upload"><input type="file" accept="image/*" onChange={e=>uploadPageBackground(e.target.files?.[0])}/>Upload page background</label><p className="se-helper">Set a page-wide background here. Section backgrounds can override it.</p><Select label="Status" value={page?.is_published===false?'draft':'published'} options={['published','draft']} onChange={v=>updatePage('is_published',v==='published')}/><label className="se-check"><input type="checkbox" checked={!!page?.show_in_navigation} onChange={e=>updatePage('show_in_navigation',e.target.checked)}/> Show in navigation</label></div></aside>
    </div>{message&&<div className="se-toast">{message}</div>}{modal&&<AddModal modal={modal} close={()=>setModal(null)} onSection={addSection} onBlock={type=>selectedSection&&addBlock(selectedSection.id,type)}/>}</div>
}

function labelFor(t){return TYPES.find(x=>x[0]===t)?.[1]||t}
function Preview({page,sections,site,services,projects,team,values,selected,setSelected,device,header,footer}){return <div className="se-public-preview" style={{backgroundColor:page?.background_color||undefined,backgroundImage:page?.background_image?`url(${page.background_image})`:undefined}}><EditableHeader header={header} selected={selected==='__header'} onSelect={()=>setSelected('__header')}/>{sections.map(s=>s.visible===false?null:<section key={s.id} className={`se-preview-section ${selected===s.id?'selected':''}`} onClick={e=>{e.stopPropagation();setSelected(s.id)}} style={{padding:s.settings?.padding==='small'?'36px 24px':s.settings?.padding==='none'?'0':'80px 24px',backgroundColor:s.settings?.background||undefined,backgroundImage:s.settings?.backgroundImage?`url(${s.settings.backgroundImage})`:undefined,backgroundSize:s.settings?.backgroundSize||'cover',backgroundPosition:s.settings?.backgroundPosition||'center',backgroundRepeat:'no-repeat'}}><div className="se-preview-inner" style={{maxWidth:`${s.settings?.maxWidth||1200}px`}}>{s.blocks.map(b=>b.visible===false?null:<div key={b.id} className={`se-preview-block ${selected===`${s.id}:${b.id}`?'selected':''}`} style={designStyle(b.settings,device)} onClick={e=>{e.stopPropagation();setSelected(`${s.id}:${b.id}`)}}><RenderBlock block={b} site={site} services={services} projects={projects} team={team} values={values}/></div>)}</div></section>)}<EditableFooter footer={footer} selected={selected==='__footer'} onSelect={()=>setSelected('__footer')}/></div>}
function EditableHeader({header,selected,onSelect}){const h=header||{};return <div className={`se-editable-header ${selected?'selected':''}`} onClick={e=>{e.stopPropagation();onSelect()}} style={{background:h.background||'#fff',color:h.textColor||'#222',borderBottom:`1px solid ${h.borderColor||'#e5e5e5'}`,position:h.sticky?'sticky':'relative',top:h.sticky?0:undefined,zIndex:h.sticky?10:undefined}}><strong style={{fontSize:`${Number(h.logoSize)||18}px`}}>{'Your Business Name'}</strong><div className="se-editable-nav">Home&nbsp;&nbsp; About&nbsp;&nbsp; Services&nbsp;&nbsp; Projects&nbsp;&nbsp; Team&nbsp;&nbsp; Contact</div></div>}

function EditableFooter({footer,selected,onSelect}){const f=footer||{};return <footer className={`se-editable-footer ${selected?'selected':''}`} onClick={e=>{e.stopPropagation();onSelect()}}><div className="se-footer-grid"><div><strong>{f.business_name||'Your Business Name'}</strong><p>{f.tagline||''}</p><div className="se-footer-socials">{(f.socials||[]).map((x,i)=><span key={x.id||i} title={x.name||'Social'}><i className={x.icon||''}/>{x.name||'Social'}</span>)}</div></div><div><h4>Explore</h4><p>About · Services · Projects · Team · Contact</p></div><div><h4>Contact</h4><p>{f.email||''}<br/>{f.phone||''}<br/>{f.address||''}</p></div></div><div className="se-footer-bottom">© {new Date().getFullYear()} {f.business_name||'Your Business Name'} · {f.tagline||'Designed with intention.'}</div></footer>}
function RenderBlock({block,site,services,projects,team,values}){const c=block.settings||{};switch(block.type){case'hero':return <div className="pv-hero"><div><p className="eyebrow">{c.eyebrow}</p><h1>{c.title}</h1>{c.description&&<p className="hero-description">{c.description}</p>}<div className="btn-group">{c.primaryText&&<span className="btn btn-dark">{c.primaryText}</span>}{c.secondaryText&&<span className="text-link">{c.secondaryText} ↗</span>}</div></div><div className="hero-visual">{c.image?<img src={c.image} alt=""/>:<div className="placeholder-visual"><div className="visual-label">Add image</div></div>}</div></div>;case'text':return <div className="pv-text" style={{textAlign:c.alignment||'left'}}><p className="eyebrow">{c.eyebrow}</p>{c.title&&<h2>{c.title}</h2>}{c.text&&<p style={{whiteSpace:'pre-wrap'}}>{c.text}</p>}</div>;case'image':return c.url?<figure style={{margin:0}}><img src={c.url} alt={c.alt||''} style={{width:'100%',height:`${Number(c.height)||500}px`,objectFit:c.fit||'cover'}}/>{c.caption&&<figcaption>{c.caption}</figcaption>}</figure>:<div className="pv-image pv-image-placeholder">Add image</div>;case'button':return <div style={{textAlign:c.alignment||'left'}}><span className="btn btn-dark">{c.text}</span></div>;case'video':return c.url?<iframe className="pv-video" src={c.url} title={c.title||'Video'} allowFullScreen/>:<div className="pv-image pv-image-placeholder">Add video</div>;case'divider':return <hr/>;case'spacer':return <div style={{height:Number(c.height)||80}}/>;case'services':return <Collection type="services" title={c.title} eyebrow={c.eyebrow} items={services} limit={c.limit}/>;case'projects':return <Collection type="projects" title={c.title} eyebrow={c.eyebrow} items={projects} limit={c.limit}/>;case'team':return <Collection type="team" title={c.title} eyebrow={c.eyebrow} items={team} limit={c.limit}/>;case'values':return <Collection type="values" title={c.title} eyebrow={c.eyebrow} items={values} limit={c.limit}/>;case'contact':return <div className="pv-text"><p className="eyebrow">{c.eyebrow}</p><h2>{c.title}</h2><p>{c.description}</p><div className="pv-contact-box">{site?.email}<br/>{site?.phone}<br/>{site?.address}</div></div>;default:return null}}
function Collection({type,title,eyebrow,items,limit}){const list=limit?items.slice(0,Number(limit)):items;return <div><div className="section-intro"><p className="eyebrow">{eyebrow}</p>{title&&<h2>{title}</h2>}</div><div className={`pv-grid ${type}`}>{list.map((x,i)=><article key={x.id||i}>{(x.image_url||x.image)&&<img src={x.image_url||x.image} alt={x.title||x.name||''}/>}<p className="card-number">{x.category||String(i+1).padStart(2,'0')}</p><h3>{x.title||x.name}</h3><p>{x.description||x.bio||''}</p></article>)}</div></div>}

function loadHeaderSettings(){try{return {...{background:'#ffffff',textColor:'#222222',borderColor:'#e5e5e5',sticky:false,logoSize:18},...(JSON.parse(localStorage.getItem('site_header_settings')||'{}'))}}catch{return {background:'#ffffff',textColor:'#222222',borderColor:'#e5e5e5',sticky:false,logoSize:18}}}
function saveHeaderSettings(v){try{localStorage.setItem('site_header_settings',JSON.stringify(v||{}))}catch{}}

function designStyle(c={},device='desktop'){const st={}; if(c.textColor)st.color=c.textColor; if(c.fontFamily)st.fontFamily=c.fontFamily; if(c.fontSize)st.fontSize=`${Number(c.fontSize)}px`; if(c.fontWeight)st.fontWeight=c.fontWeight; if(c.lineHeight)st.lineHeight=c.lineHeight; if(c.letterSpacing)st.letterSpacing=`${Number(c.letterSpacing)}px`; if(c.blockBackground)st.background=c.blockBackground; if(c.radius!=null&&c.radius!=='')st.borderRadius=`${Number(c.radius)}px`; if(c.shadow)st.boxShadow=c.shadow; if(c.blockPadding)st.padding=c.blockPadding; if(c.blockMargin)st.margin=c.blockMargin; if(c.maxWidth)st.maxWidth=`${Number(c.maxWidth)}px`; if(c.opacity!=null&&c.opacity!=='')st.opacity=Number(c.opacity); if(device==='mobile'){if(c.mobileFontSize)st.fontSize=`${Number(c.mobileFontSize)}px`;if(c.mobilePadding)st.padding=c.mobilePadding;if(c.mobileMargin)st.margin=c.mobileMargin;if(c.mobileMaxWidth)st.maxWidth=`${Number(c.mobileMaxWidth)}px`;if(c.mobileAlignment)st.textAlign=c.mobileAlignment;} return st}
function linkProps(c={}){const action=c.action||'url'; if(action==='email')return `mailto:${c.email||c.url||''}`; if(action==='phone')return `tel:${c.phone||c.url||''}`; if(action==='whatsapp'){const n=(c.whatsapp||c.url||'').replace(/[^0-9+]/g,''); return `https://wa.me/${n.replace(/^\+/,'')}`} if(action==='instagram')return c.instagram||c.url||'#'; if(action==='facebook')return c.facebook||c.url||'#'; if(action==='tiktok')return c.tiktok||c.url||'#'; if(action==='linkedin')return c.linkedin||c.url||'#'; return c.url||'#'}
function LinkSettings({c,update}){return <><Select label="Action" value={c.action||'url'} options={['url','instagram','whatsapp','facebook','tiktok','linkedin','email','phone']} onChange={v=>update({action:v})}/>{(c.action||'url')==='email'?<Field label="Email" value={c.email} onChange={v=>update({email:v})}/>:null}{c.action==='phone'?<Field label="Phone" value={c.phone} onChange={v=>update({phone:v})}/>:null}{c.action==='whatsapp'?<Field label="WhatsApp number" value={c.whatsapp} onChange={v=>update({whatsapp:v})}/>:null}{['instagram','facebook','tiktok','linkedin'].includes(c.action)?<Field label={`${c.action} URL`} value={c[c.action]} onChange={v=>update({[c.action]:v})} placeholder="https://…"/>:null}{(!c.action||c.action==='url')&&<Field label="Link URL" value={c.url} onChange={v=>update({url:v})} placeholder="/about or https://…"/>}<label className="se-check"><input type="checkbox" checked={!!c.newTab} onChange={e=>update({newTab:e.target.checked})}/> Open in new tab</label></>}
function DesignFields({c,update}){return <div className="se-design-fields"><div className="se-subhead">DESIGN</div><ColorField label="Text color" value={c.textColor||''} onChange={v=>update({textColor:v})}/><Select label="Font family" value={c.fontFamily||'inherit'} options={['inherit','Arial','Georgia','Helvetica','Inter','Montserrat','Poppins','Playfair Display','Times New Roman']} onChange={v=>update({fontFamily:v==='inherit'?'':v})}/><Field label="Font size (px)" type="number" value={c.fontSize||''} onChange={v=>update({fontSize:v})}/><Select label="Font weight" value={String(c.fontWeight||'')} options={['','300','400','500','600','700','800']} onChange={v=>update({fontWeight:v})}/><Field label="Line height" value={c.lineHeight||''} onChange={v=>update({lineHeight:v})} placeholder="1.4"/><Field label="Letter spacing (px)" type="number" value={c.letterSpacing||''} onChange={v=>update({letterSpacing:v})}/><ColorField label="Block background" value={c.blockBackground||''} onChange={v=>update({blockBackground:v})}/><Field label="Border radius (px)" type="number" value={c.radius??''} onChange={v=>update({radius:v})}/><Select label="Shadow" value={c.shadow||''} options={['','0 2px 12px rgba(0,0,0,.08)','0 8px 30px rgba(0,0,0,.12)','0 16px 50px rgba(0,0,0,.16)']} onChange={v=>update({shadow:v})}/><Field label="Max width (px)" type="number" value={c.maxWidth||''} onChange={v=>update({maxWidth:v})}/><Field label="Padding" value={c.blockPadding||''} onChange={v=>update({blockPadding:v})} placeholder="20px 0"/><Field label="Margin" value={c.blockMargin||''} onChange={v=>update({blockMargin:v})} placeholder="0 auto"/><Field label="Opacity" type="number" value={c.opacity??''} onChange={v=>update({opacity:v})} placeholder="1"/><div className="se-subhead">MOBILE OVERRIDES</div><Field label="Mobile font size (px)" type="number" value={c.mobileFontSize||''} onChange={v=>update({mobileFontSize:v})}/><Select label="Mobile alignment" value={c.mobileAlignment||''} options={['','left','center','right']} onChange={v=>update({mobileAlignment:v})}/><Field label="Mobile max width (px)" type="number" value={c.mobileMaxWidth||''} onChange={v=>update({mobileMaxWidth:v})}/><Field label="Mobile padding" value={c.mobilePadding||''} onChange={v=>update({mobilePadding:v})} placeholder="16px"/><Field label="Mobile margin" value={c.mobileMargin||''} onChange={v=>update({mobileMargin:v})} placeholder="0 auto"/><button type="button" className="se-clear-design" onClick={()=>update({textColor:'',fontFamily:'',fontSize:'',fontWeight:'',lineHeight:'',letterSpacing:'',blockBackground:'',radius:'',shadow:'',maxWidth:'',blockPadding:'',blockMargin:'',opacity:'',mobileFontSize:'',mobileAlignment:'',mobileMaxWidth:'',mobilePadding:'',mobileMargin:''})}>Reset design</button></div>}
function Inspector({header,updateHeader,footer,updateFooter,section,block,updateSection,updateBlock,removeSection,removeBlock,duplicateSection,moveSection,sectionIndex,addBlock,uploadImage,moveBlock,duplicateBlock}){if(header)return <HeaderInspector header={header} update={updateHeader}/>;if(footer)return <FooterInspector footer={footer} update={updateFooter}/>;if(!section)return <div className="se-inspector"><div className="se-empty-inspector"><span>↖</span><strong>Select something to edit</strong><p>Click a section, block, or Footer in the preview.</p></div></div>;if(block)return <div className="se-inspector"><Head title={labelFor(block.type)} kind="BLOCK" onDelete={()=>removeBlock(section.id,block.id)}/><div className="se-inspector-actions"><button onClick={()=>moveBlock(section.id,block.id,-1)}>↑ Move up</button><button onClick={()=>moveBlock(section.id,block.id,1)}>↓ Move down</button><button onClick={()=>duplicateBlock(section.id,block.id)}>Duplicate</button></div><BlockFields block={block} c={block.settings||{}} update={p=>updateBlock(section.id,block.id,p)} upload={f=>uploadImage(f,section.id,block.id)}/></div>;return <div className="se-inspector"><Head title={section.name} kind="SECTION" onDelete={()=>removeSection(section.id)}/><Field label="Section name" value={section.name} onChange={v=>updateSection(section.id,{name:v})}/><ColorField label="Background color" value={section.settings?.background||''} onChange={v=>updateSection(section.id,{settings:{...section.settings,background:v}})}/><Field label="Background image URL" value={section.settings?.backgroundImage||''} onChange={v=>updateSection(section.id,{settings:{...section.settings,backgroundImage:v}})} placeholder="https://…"/><Select label="Background size" value={section.settings?.backgroundSize||'cover'} options={['cover','contain','auto']} onChange={v=>updateSection(section.id,{settings:{...section.settings,backgroundSize:v}})}/><Select label="Background position" value={section.settings?.backgroundPosition||'center'} options={['center','top','bottom','left','right']} onChange={v=>updateSection(section.id,{settings:{...section.settings,backgroundPosition:v}})}/><Select label="Spacing" value={section.settings?.padding||'large'} options={['none','small','large']} onChange={v=>updateSection(section.id,{settings:{...section.settings,padding:v}})}/><Field label="Max width" type="number" value={section.settings?.maxWidth||1200} onChange={v=>updateSection(section.id,{settings:{...section.settings,maxWidth:Number(v)||1200}})}/><div className="se-inspector-actions"><button onClick={()=>moveSection(sectionIndex,-1)}>↑ Move up</button><button onClick={()=>moveSection(sectionIndex,1)}>↓ Move down</button><button onClick={()=>duplicateSection(section.id)}>Duplicate</button></div><div className="se-add-block-inspector"><strong>Add block</strong><div>{TYPES.map(([t,l])=><button key={t} onClick={()=>addBlock(t)}>＋ {l}</button>)}</div></div></div>}
function HeaderInspector({header,update}){return <div className="se-inspector"><Head title="Header" kind="GLOBAL" onDelete={()=>{}}/><div className="se-subhead">HEADER STYLE</div><ColorField label="Background" value={header.background||''} onChange={v=>update({background:v})}/><ColorField label="Text color" value={header.textColor||''} onChange={v=>update({textColor:v})}/><ColorField label="Border color" value={header.borderColor||''} onChange={v=>update({borderColor:v})}/><Field label="Logo text size (px)" type="number" value={header.logoSize||18} onChange={v=>update({logoSize:v})}/><label className="se-check"><input type="checkbox" checked={!!header.sticky} onChange={e=>update({sticky:e.target.checked})}/> Sticky header</label><div className="se-save-note">Header styling is global and is saved for the site.</div></div>}

function FooterInspector({footer,update}){const socials=footer.socials||[];function setSocial(id,p){update({socials:socials.map((s,i)=>(String(s.id||`new-${i}`)===String(id)?{...s,...p}:s))})}function addSocial(platform='instagram'){const labels={instagram:'Instagram',whatsapp:'WhatsApp',facebook:'Facebook',tiktok:'TikTok',linkedin:'LinkedIn',youtube:'YouTube',x:'X'};const icons={instagram:'fa-brands fa-instagram',whatsapp:'fa-brands fa-whatsapp',facebook:'fa-brands fa-facebook-f',tiktok:'fa-brands fa-tiktok',linkedin:'fa-brands fa-linkedin-in',youtube:'fa-brands fa-youtube',x:'fa-brands fa-x-twitter'};update({socials:[...socials,{id:null,name:labels[platform]||'Social',url:'',icon:icons[platform]||''}]})}function removeSocial(id){update({socials:socials.filter((s,i)=>String(s.id||`new-${i}`)!==String(id))})}return <div className="se-inspector"><Head title="Footer" kind="GLOBAL" onDelete={()=>{}}/><div className="se-subhead">BUSINESS</div><Field label="Business name" value={footer.business_name} onChange={v=>update({business_name:v})}/><Field label="Tagline" value={footer.tagline} onChange={v=>update({tagline:v})} area/><div className="se-subhead">CONTACT</div><Field label="Email" value={footer.email} onChange={v=>update({email:v})}/><Field label="Phone" value={footer.phone} onChange={v=>update({phone:v})}/><Field label="Address" value={footer.address} onChange={v=>update({address:v})} area/><div className="se-subhead">SOCIAL LINKS</div>{socials.map((x,i)=>{const sid=x.id||`new-${i}`;return <div className="se-footer-social-edit" key={sid}><div className="se-social-row-head"><strong>{x.name||`Social ${i+1}`}</strong><button type="button" className="se-danger-mini" onClick={()=>removeSocial(sid)}>Delete</button></div><Select label="Platform" value={String(x.name||'Social').toLowerCase()} options={['instagram','whatsapp','facebook','tiktok','linkedin','youtube','x','social']} onChange={v=>{const labels={instagram:'Instagram',whatsapp:'WhatsApp',facebook:'Facebook',tiktok:'TikTok',linkedin:'LinkedIn',youtube:'YouTube',x:'X',social:'Social'};const icons={instagram:'fa-brands fa-instagram',whatsapp:'fa-brands fa-whatsapp',facebook:'fa-brands fa-facebook-f',tiktok:'fa-brands fa-tiktok',linkedin:'fa-brands fa-linkedin-in',youtube:'fa-brands fa-youtube',x:'fa-brands fa-x-twitter'};setSocial(sid,{name:labels[v],icon:icons[v]||x.icon||''})}}/><Field label="URL" value={x.url} onChange={v=>setSocial(sid,{url:v})} placeholder="https://…"/><Field label="Icon class" value={x.icon} onChange={v=>setSocial(sid,{icon:v})}/></div>})}<div className="se-social-add-grid"><button type="button" onClick={()=>addSocial('instagram')}>+ Instagram</button><button type="button" onClick={()=>addSocial('whatsapp')}>+ WhatsApp</button><button type="button" onClick={()=>addSocial('facebook')}>+ Facebook</button><button type="button" onClick={()=>addSocial('linkedin')}>+ LinkedIn</button><button type="button" onClick={()=>addSocial('tiktok')}>+ TikTok</button><button type="button" onClick={()=>addSocial('youtube')}>+ YouTube</button><button type="button" onClick={()=>addSocial('x')}>+ X</button></div><div className="se-save-note">Add or remove icons here. Changes are global and apply to every page. Click Save to apply them.</div></div>}
function Head({title,kind,onDelete}){return <div className="se-inspector-head"><div><small>{kind}</small><h3>{title}</h3></div><button onClick={onDelete}>🗑</button></div>}
function BlockFields({block,c,update,upload}){let body=null;if(block.type==='hero')body=<><Field label="Eyebrow" value={c.eyebrow} onChange={v=>update({eyebrow:v})}/><Field label="Headline" value={c.title} onChange={v=>update({title:v})} area/><Field label="Description" value={c.description} onChange={v=>update({description:v})} area/><ImageField label="Hero image" value={c.image} onChange={v=>update({image:v})} upload={upload}/><Field label="Primary button" value={c.primaryText} onChange={v=>update({primaryText:v})}/><LinkSettings c={{...c,url:c.primaryUrl,action:c.primaryAction,email:c.primaryEmail,phone:c.primaryPhone,whatsapp:c.primaryWhatsapp,instagram:c.primaryInstagram}} update={p=>{const q={...p};if(p.url!=null)q.primaryUrl=p.url;if(p.action!=null)q.primaryAction=p.action;if(p.email!=null)q.primaryEmail=p.email;if(p.phone!=null)q.primaryPhone=p.phone;if(p.whatsapp!=null)q.primaryWhatsapp=p.whatsapp;if(p.instagram!=null)q.primaryInstagram=p.instagram;delete q.url;delete q.action;delete q.email;delete q.phone;delete q.whatsapp;delete q.instagram;update(q)}}/><Field label="Secondary button" value={c.secondaryText} onChange={v=>update({secondaryText:v})}/><LinkSettings c={{...c,url:c.secondaryUrl,action:c.secondaryAction,email:c.secondaryEmail,phone:c.secondaryPhone,whatsapp:c.secondaryWhatsapp,instagram:c.secondaryInstagram}} update={p=>{const q={...p};if(p.url!=null)q.secondaryUrl=p.url;if(p.action!=null)q.secondaryAction=p.action;delete q.url;delete q.action;update(q)}}/></>;else if(block.type==='text')body=<><Field label="Eyebrow" value={c.eyebrow} onChange={v=>update({eyebrow:v})}/><Field label="Heading" value={c.title} onChange={v=>update({title:v})} area/><Field label="Text" value={c.text} onChange={v=>update({text:v})} area/><Select label="Alignment" value={c.alignment||'left'} options={['left','center','right']} onChange={v=>update({alignment:v})}/></>;else if(block.type==='image')body=<><ImageField label="Image" value={c.url} onChange={v=>update({url:v})} upload={upload}/><Field label="Alt text" value={c.alt} onChange={v=>update({alt:v})}/><Field label="Caption" value={c.caption} onChange={v=>update({caption:v})}/><Field label="Height" type="number" value={c.height} onChange={v=>update({height:Number(v)||0})}/><Select label="Fit" value={c.fit||'cover'} options={['cover','contain','fill']} onChange={v=>update({fit:v})}/><Select label="Position" value={c.position||'center'} options={['center','top','bottom','left','right']} onChange={v=>update({position:v})}/></>;else if(block.type==='button')body=<><Field label="Button text" value={c.text} onChange={v=>update({text:v})}/><LinkSettings c={c} update={update}/><Select label="Alignment" value={c.alignment||'left'} options={['left','center','right']} onChange={v=>update({alignment:v})}/><Select label="Style" value={c.style||'dark'} options={['dark','light','outline','text']} onChange={v=>update({style:v})}/></>;else if(block.type==='video')body=<><Field label="Embed URL" value={c.url} onChange={v=>update({url:v})}/><Field label="Title" value={c.title} onChange={v=>update({title:v})}/><Select label="Aspect ratio" value={c.aspect||'16/9'} options={['16/9','4/3','1/1','9/16']} onChange={v=>update({aspect:v})}/></>;else if(['services','projects','team','values'].includes(block.type))body=<><Field label="Eyebrow" value={c.eyebrow} onChange={v=>update({eyebrow:v})}/><Field label="Heading" value={c.title} onChange={v=>update({title:v})} area/><Field label="Description" value={c.description} onChange={v=>update({description:v})} area/><Field label="Items to show (0 = all)" type="number" value={c.limit} onChange={v=>update({limit:Number(v)||0})}/></>;else if(block.type==='contact')body=<><Field label="Eyebrow" value={c.eyebrow} onChange={v=>update({eyebrow:v})}/><Field label="Heading" value={c.title} onChange={v=>update({title:v})} area/><Field label="Description" value={c.description} onChange={v=>update({description:v})} area/><LinkSettings c={{...c,action:c.action||'url',url:c.url||'/contact'}} update={update}/></>;else if(block.type==='spacer')body=<Field label="Height (px)" type="number" value={c.height} onChange={v=>update({height:Number(v)||0})}/>;else body=<p className="se-helper">This block has no settings.</p>;return <>{body}<DesignFields c={c} update={update}/></>}
function Field({label,value,onChange,area,type='text',placeholder=''}){return <label className="se-field"><span>{label}</span>{area?<textarea value={value??''} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>:<input type={type} value={value??''} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}</label>}
function ColorField({label,value,onChange}){return <label className="se-field se-color-field"><span>{label}</span><div className="se-color-row"><input type="color" value={/^#[0-9a-fA-F]{6}$/.test(value||'')?value:'#ffffff'} onChange={e=>onChange(e.target.value)}/><input value={value||''} onChange={e=>onChange(e.target.value)} placeholder="#ffffff or transparent"/><button type="button" onClick={()=>onChange('')}>Clear</button></div></label>}
function Select({label,value,options,onChange}){return <label className="se-field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o}>{o}</option>)}</select></label>}
function ImageField({label,value,onChange,upload}){return <div className="se-field"><span>{label}</span><input value={value||''} onChange={e=>onChange(e.target.value)} placeholder="Image URL"/><label className="se-upload"><input type="file" accept="image/*" onChange={e=>upload(e.target.files?.[0])}/>Upload / replace image</label>{value&&<><img className="se-thumb" src={value} alt=""/><button className="se-remove-image" onClick={()=>onChange('')}>Remove image</button></>}</div>}
function AddModal({modal,close,onSection,onBlock}){const [search,setSearch]=useState('');const options=modal.kind==='section'?[['hero','Hero'],['text','Text section'],['image','Image section'],['services','Services section'],['projects','Projects section'],['team','Team section'],['values','Values section'],['contact','Contact section'],['section','Blank section']]:TYPES;return <div className="se-modal-backdrop" onMouseDown={close}><div className="se-modal" onMouseDown={e=>e.stopPropagation()}><div className="se-modal-head"><div><small>ADD {modal.kind.toUpperCase()}</small><h2>Choose a {modal.kind}</h2></div><button onClick={close}>×</button></div><input className="se-search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search sections and blocks…"/><div className="se-option-grid">{options.filter(x=>x[1].toLowerCase().includes(search.toLowerCase())).map(([t,l])=><button key={t} onClick={()=>modal.kind==='section'?onSection(t):onBlock(t)}><span>{icon(t)}</span><strong>{l}</strong><small>{description(t)}</small></button>)}</div></div></div>}
function icon(t){return {hero:'✦',text:'T',image:'▧',button:'↗',video:'▶',divider:'—',spacer:'↕',services:'▦',projects:'▧',team:'◎',values:'◇',contact:'✉',section:'＋'}[t]||'•'}
function description(t){return {hero:'Large visual with headline and calls to action',text:'Heading and body copy',image:'Image with caption and sizing',button:'Call to action link',video:'Embedded video',divider:'Visual separator',spacer:'Vertical spacing',services:'Your existing services database',projects:'Your existing projects database',team:'Your existing team database',values:'Your existing values database',contact:'Contact information and CTA',section:'Start with an empty section'}[t]||''}
